  KEY `index_driver_name` (`driver_name`),
  KEY `index_driver_licence` (`driver_licence`),
  KEY `index_driver_contact` (`driver_contact`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb3;



